<?php
namespace App\Http\Controllers;
use App\Models\{ExchangeRate,Currency};use App\Services\FxRevaluationService;use Illuminate\Http\Request;
class FxController {public function index(){return view('fx.index',['rates'=>ExchangeRate::forCompany(auth()->user()->company_id)->with('currency')->latest('rate_date')->paginate(100),'currencies'=>Currency::where('active',1)->get()]);}public function store(Request $r){$d=$r->validate(['currency_id'=>'required|integer','rate_date'=>'required|date','rate'=>'required|decimal:1,10','source'=>'nullable|string|max:255']);$d['company_id']=$r->user()->company_id;$d['created_by']=$r->user()->id;ExchangeRate::updateOrCreate(['company_id'=>$d['company_id'],'currency_id'=>$d['currency_id'],'rate_date'=>$d['rate_date']],$d);return back()->with('ok','Exchange rate saved.');}public function revalue(Request $r){$d=$r->validate(['date'=>'required|date']);$j=app(FxRevaluationService::class)->run($r->user()->company_id,$r->user()->id,$d['date']);return $j?redirect()->route('journals.show',$j):back()->with('ok','No FX revaluation adjustment was required.');}}
